require_once __DIR__.'/includes/config.php'; require_auth(); log_page_view('flags.php','Banderas');
$msg=''; $err=''; $hintMsg=''; $selectedHintFlag=max(1,min(20,(int)($_POST['hint_flag']??$_GET['hint_flag']??1)));
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!attempt_is_active()){$err='El laboratorio ya fue finalizado. La captura de banderas y solicitud de pistas está cerrada.';}
 else{
  verify_csrf(); $action=(string)($_POST['action']??'flag');
  if($action==='hint'){
    $flagNo=$selectedHintFlag;
    $q=db()->prepare("SELECT h.hint_order,h.hint_text FROM flag_hints h WHERE h.flag_number=? AND NOT EXISTS (SELECT 1 FROM lab_hint_usage u WHERE u.attempt_id=? AND u.flag_number=h.flag_number AND u.hint_order=h.hint_order) ORDER BY h.hint_order LIMIT 1");
    $q->execute([$flagNo,current_attempt_id()]); $hint=$q->fetch();
    if(!$hint){$hintMsg='No quedan más pistas configuradas para el reto '.sprintf('%02d',$flagNo).'.';}
    else{
      $i=db()->prepare("INSERT INTO lab_hint_usage(attempt_id,student_id,flag_number,hint_order) VALUES(?,?,?,?)");
      $i->execute([current_attempt_id(),current_student_id(),$flagNo,(int)$hint['hint_order']]);
      log_activity('HINT_REQUESTED','Pista consultada','Reto '.sprintf('%02d',$flagNo).' · pista '.(int)$hint['hint_order'],['flag_number'=>$flagNo,'hint_order'=>(int)$hint['hint_order']],'auditor','notice');
      $hintMsg='Reto '.sprintf('%02d',$flagNo).' · Pista '.(int)$hint['hint_order'].': '.$hint['hint_text'];
    }
  } else {
    $flag=trim((string)($_POST['flag']??'')); $note=trim((string)($_POST['note']??''));
    $q=db()->prepare("SELECT * FROM flag_catalog WHERE flag_value=?"); $q->execute([$flag]); $cat=$q->fetch();
    if(!$cat){$err='La bandera no es válida.'; log_activity('FLAG_REJECTED','Intento de bandera rechazado','Se intentó registrar una bandera que no pertenece al catálogo.',['submitted'=>$flag]);}
    else{
      $dup=db()->prepare("SELECT id,created_at FROM flag_submissions WHERE attempt_id=? AND flag_number=? AND status='accepted' LIMIT 1"); $dup->execute([current_attempt_id(),$cat['flag_number']]); $d=$dup->fetch();
      if($d){$err='La bandera '.sprintf('%02d',$cat['flag_number']).' ya fue registrada el '.$d['created_at'].'.'; log_activity('FLAG_DUPLICATE','Bandera duplicada','Se volvió a enviar una bandera ya acreditada.',['flag_number'=>(int)$cat['flag_number']]);}
      else{
       db()->beginTransaction();
       try{
         $ins=db()->prepare("INSERT INTO flag_submissions(attempt_id,flag_number,flag_value,status,note,submitted_by) VALUES(?,?,?,'accepted',?,?)");
         $student=current_student(); $ins->execute([current_attempt_id(),$cat['flag_number'],$flag,$note,$student['matricula']??'']);
         $autoCheck=db()->prepare("INSERT INTO lab_checklist_state(attempt_id,student_id,flag_number,item_index,is_checked,updated_at) VALUES(?,?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE is_checked=1,updated_at=NOW()");
         foreach([0,1,2] as $autoItem){$autoCheck->execute([current_attempt_id(),current_student_id(),(int)$cat['flag_number'],$autoItem]);}
         $ev=db()->prepare("INSERT IGNORE INTO scenario_events(attempt_id,event_code,flag_number,source,detail) VALUES(?,?,?,?,?)");
         $ev->execute([current_attempt_id(),'FLAG_'.sprintf('%02d',$cat['flag_number']),(int)$cat['flag_number'],'auditor-portal','Bandera validada desde Portal del Auditor']);
         $allQ=db()->prepare("SELECT COUNT(DISTINCT flag_number) FROM flag_submissions WHERE attempt_id=? AND status='accepted'"); $allQ->execute([current_attempt_id()]);
         if((int)$allQ->fetchColumn()>=20){ $ev->execute([current_attempt_id(),'ALL_FLAGS',null,'auditor-portal','Las 20 banderas del laboratorio fueron acreditadas']); }
         db()->commit();
         log_activity('FLAG_ACCEPTED','Bandera acreditada','Bandera '.sprintf('%02d',$cat['flag_number']).' registrada correctamente.',['flag_number'=>(int)$cat['flag_number'],'code_name'=>$cat['code_name'],'difficulty'=>(int)$cat['difficulty'],'weight'=>(int)$cat['weight']]);
         $msg='Bandera '.sprintf('%02d',$cat['flag_number']).' validada. El escenario fue actualizado automáticamente.';
       }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err='No fue posible registrar la bandera.';log_activity('FLAG_ERROR','Error al registrar bandera',$e->getMessage());}
      }
    }
  }
 }
}
$q=db()->prepare("SELECT c.*,s.created_at AS obtained_at,s.note FROM flag_submissions s JOIN flag_catalog c ON c.flag_number=s.flag_number WHERE s.attempt_id=? AND s.status='accepted' ORDER BY s.created_at,c.flag_number");$q->execute([current_attempt_id()]);$obtained=$q->fetchAll();
$q=db()->prepare("SELECT u.flag_number,u.hint_order,h.hint_text,u.created_at FROM lab_hint_usage u JOIN flag_hints h ON h.flag_number=u.flag_number AND h.hint_order=u.hint_order WHERE u.attempt_id=? ORDER BY u.created_at DESC,u.id DESC");$q->execute([current_attempt_id()]);$usedHints=$q->fetchAll(); $usedHintsByFlag=[]; foreach($usedHints as $uh){$usedHintsByFlag[(int)$uh['flag_number']][]=$uh;}
$q=db()->prepare("SELECT flag_number,item_index,is_checked FROM lab_checklist_state WHERE attempt_id=?");$q->execute([current_attempt_id()]);$checkRows=$q->fetchAll(); $checkState=[]; foreach($checkRows as $cr){$checkState[(int)$cr['flag_number']][(int)$cr['item_index']]=(int)$cr['is_checked']===1;}

$challengeChecklist=[
1=>['Parte de una función pública normal del portal y observa cómo están organizados sus recursos.','Comprueba si el servidor permite explorar el directorio que contiene recursos legítimos.','Distingue los documentos esperados de cualquier artefacto residual de operación o despliegue.'],
2=>['Inspecciona lo que el navegador recibe además de lo que muestra.','Busca referencias, rutas o comentarios que aporten contexto adicional.','Conserva evidencia del recurso del lado cliente donde aparezca el hallazgo.'],
3=>['Compara objetos similares dentro de una misma función.','Verifica si cambiar un identificador modifica el recurso consultado.','Confirma si el servidor valida que el objeto pertenece al usuario autenticado.'],
4=>['Revisa rastros de versiones anteriores y archivos residuales.','Comprueba si copias o respaldos quedaron accesibles.','Explica qué información adicional aporta el artefacto encontrado.'],
5=>['Identifica una función del portal que genere una descarga dinámica y observa qué solicitud realiza el navegador.','Determina qué parámetro controla el contenido solicitado y prueba una entrada no contemplada por la interfaz.','Compara la respuesta del servidor y registra cualquier detalle técnico que no debería exponerse al usuario final.'],
6=>['Accede con una cuenta ciudadana a una función marcada para personal autorizado y registra la respuesta del servidor.','Inspecciona la solicitud HTTP y sus cookies para identificar si algún dato controlado por el cliente parece representar el rol o privilegio.','Modifica únicamente ese dato, repite la solicitud y comprueba si el servidor permite ejecutar una operación administrativa con la misma sesión ciudadana.'],
7=>['Confirma si la respuesta de la aplicación puede controlarse mediante una condición SQL verdadera o falsa.','Utiliza el canal booleano para identificar la base de datos y enumerar su estructura.','Localiza información de validación relevante e infiere su contenido sin depender de errores SQL ni de resultados mostrados directamente.'],
8=>['Identifica un campo de entrada cuyo contenido se almacene y vuelva a mostrarse posteriormente.','Comprueba si la salida se inserta en contexto HTML sin codificación y prueba una ejecución JavaScript inocua dentro del laboratorio.','Inspecciona el HTML de la vista vulnerable, localiza el mecanismo de acreditación disponible y demuéstralo mediante una petición HTTP originada por tu JavaScript almacenado.'],
9=>['Identifica un parámetro utilizado por una función legítima para seleccionar un archivo dentro de un directorio previsto.','Comprueba si secuencias de navegación de directorios permiten salir de la ubicación esperada y valida el comportamiento con archivos estándar y previsibles del sistema operativo del laboratorio.','Documenta la profundidad necesaria, la petición utilizada y la evidencia de que el servidor entregó un archivo ajeno al directorio autorizado.'],
10=>['Registra el identificador de sesión que el portal entrega antes de autenticarte.','Autentícate y compara si ese identificador cambia al pasar de una sesión anónima a una sesión autenticada.','Si permanece igual, reutiliza exclusivamente ese identificador previo desde un segundo cliente y comprueba si una página protegida reconoce la sesión sin solicitar credenciales.'],
11=>['Navega por Mi portal y observa las solicitudes HTTP que el frontend genera en segundo plano.','Inspecciona las respuestas JSON completas y busca relaciones o rutas que la interfaz no represente visualmente.','Solicita el recurso no documentado encontrado y documenta método, autenticación, contenido y evidencia de que forma parte de la superficie real de la aplicación.'],
12=>['Retoma el endpoint histórico descubierto en el reto anterior e identifica qué parámetro selecciona la cuenta de servicio consultada.','Mantén la misma sesión autenticada y modifica únicamente el identificador del objeto; compara la respuesta de tu cuenta con la de otro identificador válido del laboratorio.','Determina si el servidor comprueba la propiedad del objeto y conserva como evidencia la petición, el código HTTP y sólo los campos mínimos necesarios para demostrar el acceso cruzado.'],
13=>['Selecciona un recibo pendiente y documenta la regla visible del flujo: el importe se fija al saldo total y la operación debe liquidar el recibo completo.','Intercepta o edita la solicitud de confirmación manteniendo la misma sesión, cuenta y factura; modifica únicamente el valor monto por un importe positivo inferior al saldo esperado.','Compara el pago registrado con el estado final del recibo y del saldo de la cuenta. Determina si el servidor volvió a validar el importe autorizado antes de dar la operación por liquidada.'],
14=>['Desde Contrataciones utiliza la función pública Validar vínculo de un contrato y registra los identificadores de contrato y proveedor que la aplicación envía.','Mantén el mismo contrato y cambia únicamente provider_id por el ID de otro proveedor vigente que puedas observar en el padrón público.','Compara el resultado legítimo con el modificado y determina si el servicio valida la relación entre ambas entidades o sólo la existencia y vigencia de cada registro por separado.'],
15=>['Visita Infraestructura estratégica y observa las solicitudes que la página genera para mostrar el estado de integración del Centro de Operaciones.','Inspecciona la respuesta completa del servicio de estado e identifica metadatos de diagnóstico que la interfaz no muestra: componentes, fronteras de confianza, segmentos de red, rutas de aplicación o nombres de servicios internos.','Construye un mapa mínimo de dependencias desde el portal web hasta el puente operacional e incluye cualquier zona o CIDR expuesto. Comprueba únicamente la ruta de aplicación publicada y registra su respuesta restringida; los nombres marcados como internos no son destinos accesibles desde el navegador.'],
16=>['Retoma el gateway restringido y el segmento operacional documentados en el reto anterior. Registra qué política declara el servidor cuando responde HTTP 403.','Investiga cómo los proxies HTTP comunican la dirección original del cliente y prueba si el gateway confía en un encabezado controlable por la petición para decidir que el origen pertenece a ese segmento.','Si logras cruzar la frontera, conserva como evidencia la solicitud modificada, los encabezados de validación y la puerta de entrada operacional revelada por el gateway. En este reto todavía no debes obtener variables de proceso ni ejecutar acciones de control.'],
17=>['Retoma la única ruta operacional revelada por el gateway y confirma que conduce al acceso legítimo del Centro de Operaciones.','Inspecciona los recursos que carga esa página e identifica el cliente JavaScript compartido por la aplicación. A partir de él determina qué endpoint utiliza el HMI para refrescar telemetría.','Compara el control de sesión de la consola principal con el del servicio de telemetría y documenta únicamente las variables necesarias para demostrar la exposición. No ejecutes acciones de control ni accedas todavía al mantenimiento de firmware.'],
18=>['Retoma el estado de actualización visible en la telemetría y revisa el cliente web compartido para identificar el servicio que consulta el HMI cuando necesita detalles de firmware. Desde ahí sigue únicamente las rutas declaradas hasta el manifiesto.','Analiza los metadatos release y support del manifiesto. Identifica una posible identidad de mantenimiento y clasifica el verificador heredado: algoritmo probable, longitud, codificación y si contiene salt. Documenta qué evidencia respalda tu clasificación.','Trabaja el verificador exclusivamente de forma offline. Conserva el hash original, normalízalo si contiene un prefijo descriptivo y prueba primero un ataque de diccionario; después utiliza reglas o candidatos construidos con el contexto del manifiesto. Registra herramienta, modo/formato, wordlist o reglas empleadas y el candidato recuperado.','Valida el candidato recalculando el digest antes de utilizarlo y prueba la identidad deducida únicamente contra el acceso operacional del laboratorio. Confirma que el rol recuperado permite mantenimiento pero no control del HMI ni acciones sobre P-101.','Obtén el paquete aprobado y distingue integridad de autenticidad. Modifica únicamente el payload, recalcula SHA-256 y comprueba si el instalador acepta contenido no aprobado sin verificar una firma del emisor. Conserva paquete original, variante, hashes y respuesta; no alteres variables de proceso.'],
19=>['Relaciona hallazgos previos en lugar de buscar una vulnerabilidad aislada.','Construye la secuencia de pasos que conecta web, arquitectura y entorno operacional.','Conserva evidencia de cada salto de la cadena.'],
20=>['Define primero cuál es el impacto operacional simulado que debes demostrar.','Comprueba qué prerrequisitos de la cadena anterior habilitan la acción final.','Registra estado antes/después, alarmas y evidencia de recuperación del simulador.']
];

