9=>[
 ['type'=>'PortSwigger','title'=>'Path traversal','url'=>'https://portswigger.net/web-security/file-path-traversal','desc'=>'Explica cómo una aplicación que concatena un nombre de archivo con un directorio base puede permitir salir de esa ubicación mediante secuencias de traversal.'],
 ['type'=>'PortSwigger','title'=>'File path traversal, simple case','url'=>'https://portswigger.net/web-security/file-path-traversal/lab-simple','desc'=>'Laboratorio introductorio para comprender cómo modificar un parámetro de archivo y acceder a un recurso fuera del directorio previsto.'],
 ['type'=>'OWASP','title'=>'Testing Directory Traversal File Include','url'=>'https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/07-Input_Validation_Testing/11.1-Testing_for_File_Inclusion/','desc'=>'Metodología para identificar parámetros de archivo, probar secuencias de traversal y documentar el acceso a recursos fuera de la ubicación esperada.'],
