11=>[
 ['type'=>'OWASP WSTG v4.2','title'=>'Identify Application Entry Points','url'=>'https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/01-Information_Gathering/06-Identify_Application_Entry_Points/','desc'=>'WSTG-INFO-06: explica cómo identificar la superficie real de una aplicación registrando solicitudes, parámetros, encabezados y respuestas, no sólo enlaces visibles.'],
