12=>[
 ['type'=>'OWASP API Security','title'=>'API1:2023 Broken Object Level Authorization','url'=>'https://api-security.owasp.org/editions/2023/en/0xa1-broken-object-level-authorization/','desc'=>'Referencia principal de BOLA: cada endpoint que recibe un identificador de objeto debe comprobar que el usuario autenticado está autorizado para actuar sobre ese objeto.'],
 ['type'=>'OWASP WSTG','title'=>'API Broken Object Level Authorization','url'=>'https://wstg.owasp.org/latest/4-Web_Application_Security_Testing/12-API_Testing/02-API_Broken_Object_Level_Authorization/','desc'=>'WSTG-APIT-02: metodología específica para identificar parámetros de objeto y comparar el comportamiento al reutilizar la misma sesión con identificadores distintos.'],
 ['type'=>'OWASP WSTG','title'=>'Insecure Direct Object References','url'=>'https://wstg.owasp.org/latest/4-Web_Application_Security_Testing/05-Authorization/04-Insecure_Direct_Object_References/','desc'=>'Explica el patrón clásico de modificar referencias directas a registros y verificar si el servidor aplica autorización horizontal.'],
 ['type'=>'PortSwigger','title'=>'Testing for IDORs','url'=>'https://portswigger.net/burp/documentation/desktop/testing-workflow/vulnerabilities/access-controls/testing-for-idors','desc'=>'Flujo práctico para localizar identificadores controlados por el cliente, modificar sólo ese valor y comparar respuestas manteniendo el mismo contexto de autenticación.'],
 ['type'=>'PortSwigger','title'=>'Testing access controls','url'=>'https://portswigger.net/burp/documentation/desktop/testing-workflow/vulnerabilities/access-controls','desc'=>'Metodología general para comprobar controles de acceso horizontales y distinguir autenticación correcta de autorización insuficiente.']
],
13=>[
 ['type'=>'OWASP WSTG v4.2','title'=>'Introduction to Business Logic Testing','url'=>'https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/10-Business_Logic_Testing/00-Introduction_to_Business_Logic/','desc'=>'Introduce las pruebas de reglas y estados de negocio: el objetivo es comprobar si la aplicación acepta secuencias o valores que contradicen las reglas funcionales previstas.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'Business Logic Security','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Business_Logic_Security_Cheat_Sheet.html','desc'=>'Recomienda aplicar y validar reglas de negocio del lado servidor, especialmente en operaciones sensibles y cambios de estado.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'Third Party Payment Gateway Integration','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Third_Party_Payment_Gateway_Integration_Cheat_Sheet.html','desc'=>'Guía específica para flujos de pago: importe, moneda, referencia y resultado deben verificarse de forma confiable antes de actualizar el estado interno de una operación.'],
 ['type'=>'PortSwigger','title'=>'Business logic vulnerabilities','url'=>'https://portswigger.net/web-security/logic-flaws','desc'=>'Explica cómo surgen fallos cuando el servidor confía en supuestos sobre el comportamiento normal del usuario o en controles aplicados sólo por el cliente.'],
 ['type'=>'PortSwigger Lab','title'=>'Excessive trust in client-side controls','url'=>'https://portswigger.net/web-security/logic-flaws/examples/lab-logic-flaws-excessive-trust-in-client-side-controls','desc'=>'Laboratorio directamente relacionado con la manipulación de un valor económico controlado por el cliente que el servidor no vuelve a validar.']
],
14=>[
 ['type'=>'OWASP Cheat Sheet','title'=>'Authorization Cheat Sheet','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html','desc'=>'Explica autorización contextual y basada en relaciones (ReBAC): no basta con tener un rol; debe comprobarse la relación concreta entre actor, acción y objeto en cada solicitud.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'Business Logic Security','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Business_Logic_Security_Cheat_Sheet.html','desc'=>'Describe por qué el backend debe validar el significado de negocio de los identificadores y volver a comprobar propiedad, estado y relaciones en cada operación.'],
 ['type'=>'OWASP WSTG v4.2','title'=>'Testing for Insecure Direct Object References','url'=>'https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/05-Authorization_Testing/04-Testing_for_Insecure_Direct_Object_References/','desc'=>'Metodología para identificar referencias a objetos controladas por el cliente y modificar parámetros individuales para comprobar operaciones sobre registros distintos.'],
 ['type'=>'PortSwigger','title'=>'Insecure direct object references (IDOR)','url'=>'https://portswigger.net/web-security/access-control/idor','desc'=>'Explica cómo parámetros controlados por el cliente pueden seleccionar directamente registros de base de datos cuando falta una validación contextual de acceso o relación.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'Authorization Testing Automation','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Testing_Automation_Cheat_Sheet.html','desc'=>'Marco para modelar y comprobar matrices de autorización considerando sujetos, recursos, acciones y combinaciones que deberían ser rechazadas.']
],
15=>[
 ['type'=>'Firefox DevTools','title'=>'Network Monitor','url'=>'https://firefox-source-docs.mozilla.org/devtools-user/network_monitor/index.html','desc'=>'Punto de partida práctico para el reto: muestra todas las solicitudes HTTP y XHR/fetch que genera una página mientras navegas por ella.'],
 ['type'=>'Firefox DevTools','title'=>'Network request details','url'=>'https://firefox-source-docs.mozilla.org/devtools-user/network_monitor/request_details/','desc'=>'Explica cómo revisar Headers y Response de una solicitud. Es especialmente útil para inspeccionar el JSON completo que la interfaz resume u oculta.'],
 ['type'=>'OWASP WSTG v4.2','title'=>'Review Web Page Content for Information Leakage','url'=>'https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/01-Information_Gathering/05-Review_Webpage_Content_for_Information_Leakage/','desc'=>'Metodología para localizar información técnica expuesta en HTML, JavaScript y recursos auxiliares, incluyendo rutas, nombres internos y detalles de configuración.'],
 ['type'=>'OWASP WSTG v4.2','title'=>'Identify Application Entry Points','url'=>'https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/01-Information_Gathering/06-Identify_Application_Entry_Points/','desc'=>'Ayuda a registrar endpoints, respuestas y parámetros para transformar hallazgos aislados en un mapa de la superficie real de la aplicación.'],
 ['type'=>'Docker Docs','title'=>'Networking in Compose','url'=>'https://docs.docker.com/compose/how-tos/networking/','desc'=>'Explica que los servicios de Compose pueden resolverse entre contenedores por nombre dentro de su red. Ayuda a interpretar un hostname interno como ot-sim sin asumir que es accesible desde el navegador del host.'],
 ['type'=>'Docker Docs','title'=>'Publishing and exposing ports','url'=>'https://docs.docker.com/get-started/docker-concepts/running-containers/publishing-ports/','desc'=>'Aclara la diferencia entre un puerto disponible dentro de la red de contenedores y un puerto publicado hacia el host. Útil para distinguir servicio interno de ruta web alcanzable.'],
 ['type'=>'PortSwigger','title'=>'Information disclosure','url'=>'https://portswigger.net/web-security/information-disclosure','desc'=>'Explica por qué nombres de host, rutas internas y otros metadatos técnicos reducen la incertidumbre de un atacante y pueden habilitar etapas posteriores.']
],
16=>[
 ['type'=>'Firefox DevTools','title'=>'Network request details · Edit and Resend','url'=>'https://firefox-source-docs.mozilla.org/devtools-user/network_monitor/request_details/','desc'=>'Guía práctica para seleccionar la petición del gateway, revisar sus encabezados y utilizar Edit and Resend para añadir o modificar headers sin salir del navegador.'],
 ['type'=>'MDN','title'=>'¿Qué es X-Forwarded-For?','url'=>'https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/X-Forwarded-For','desc'=>'X-Forwarded-For es un encabezado HTTP utilizado por proxies y balanceadores para comunicar al servidor la dirección IP original del cliente. Puede contener una cadena de direcciones cuando existen varios intermediarios. Su valor no demuestra por sí mismo el origen real de la petición: si el servidor acepta directamente un X-Forwarded-For enviado por el cliente, ese dato puede ser falsificado. Sólo debe utilizarse para decisiones de seguridad cuando la aplicación conoce y confía en los proxies que lo agregan o reescriben.'],
 ['type'=>'IETF','title'=>'RFC 1918 · Address Allocation for Private Internets','url'=>'https://datatracker.ietf.org/doc/html/rfc1918','desc'=>'Referencia sobre rangos IPv4 privados. Ayuda a comprender por qué una organización puede reservar un segmento como 10.40.20.0/24 para una zona operacional y por qué pertenecer a ese rango no debería demostrarse únicamente con un encabezado declarado por el cliente.'],
 ['type'=>'OWASP WSTG','title'=>'Bypassing Authorization Schema','url'=>'https://wstg.owasp.org/latest/4-Web_Application_Security_Testing/05-Authorization/02-Bypassing_Authorization_Schema/','desc'=>'Referencia central del reto: OWASP incluye encabezados de proxy como X-Forwarded-For entre los elementos que deben probarse cuando una función está restringida por red, origen o esquema de autorización.'],
 ['type'=>'OWASP','title'=>'IP Spoofing via HTTP Headers','url'=>'https://community.owasp.org/pages/attacks/ip_spoofing_via_http_headers.html','desc'=>'Explica específicamente el riesgo de aceptar como dirección del cliente valores provenientes de encabezados HTTP controlables y muestra ejemplos de headers utilizados para suplantar el origen.'],
 ['type'=>'Apache HTTP Server','title'=>'mod_remoteip','url'=>'https://httpd.apache.org/docs/2.4/mod/mod_remoteip.html','desc'=>'Muestra cómo debería configurarse un servidor para aceptar la IP declarada en X-Forwarded-For únicamente cuando procede de proxies internos o de confianza definidos explícitamente.'],
 ['type'=>'PortSwigger','title'=>'Spoofing your IP address using match and replace','url'=>'https://portswigger.net/burp/documentation/desktop/testing-workflow/vulnerabilities/access-controls/using-match-and-replace','desc'=>'Ejemplo práctico de una prueba de control de acceso basada en IP: modificar un encabezado que el servidor utiliza para determinar el origen de la petición.'],
 ['type'=>'MITRE ATT&CK ICS','title'=>'Remote Services','url'=>'https://attack.mitre.org/techniques/T0886/','desc'=>'Contextualiza el impacto de una frontera mal protegida entre una aplicación IT y servicios de una red operacional, sin requerir acceso directo al servicio OT interno.']
],
17=>[
 ['type'=>'Firefox DevTools','title'=>'Network Monitor · Request list','url'=>'https://firefox-source-docs.mozilla.org/devtools-user/network_monitor/','desc'=>'Permite observar qué recursos carga la aplicación y qué peticiones realiza en segundo plano. Úsalo para distinguir documentos, JavaScript y llamadas de datos sin adivinar rutas.'],
 ['type'=>'Firefox DevTools','title'=>'Debugger · Search','url'=>'https://firefox-source-docs.mozilla.org/devtools-user/debugger/how_to/search/','desc'=>'Explica cómo buscar cadenas dentro del archivo actual o en todos los scripts del proyecto. Resulta útil para localizar términos como fetch, endpoint, api, telemetry o rutas /operations/ dentro del código cliente.'],
 ['type'=>'Firefox DevTools','title'=>'Network request details','url'=>'https://firefox-source-docs.mozilla.org/devtools-user/network_monitor/request_details/','desc'=>'Muestra cómo inspeccionar URL, método, encabezados, cookies, respuesta y causa de una petición. Sirve para comparar una solicitud autenticada del HMI con una llamada directa al mismo servicio.'],
 ['type'=>'MDN','title'=>'Using the Fetch API','url'=>'https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch','desc'=>'Explica cómo JavaScript usa fetch() para realizar peticiones HTTP. Ayuda a reconocer en el código cliente qué endpoints consume una interfaz dinámica y qué información viaja en cada llamada.'],
 ['type'=>'OWASP WSTG','title'=>'Identify Application Entry Points','url'=>'https://wstg.owasp.org/latest/4-Web_Application_Security_Testing/01-Information_Gathering/06-Identify_Application_Entry_Points/','desc'=>'Metodología para inventariar puntos de entrada observando navegación, peticiones, parámetros y recursos del lado cliente. En este reto debe utilizarse antes de recurrir a enumeración o adivinación de URLs.'],
 ['type'=>'OWASP WSTG','title'=>'Testing for Bypassing Authorization Schema','url'=>'https://wstg.owasp.org/latest/4-Web_Application_Security_Testing/05-Authorization/02-Bypassing_Authorization_Schema/','desc'=>'Guía para comparar recursos protegidos y servicios auxiliares con y sin una sesión válida, verificando si todos aplican la misma decisión de autorización.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'Authentication Cheat Sheet','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html','desc'=>'Aclara cómo se establece la identidad de un usuario y por qué estar en una red determinada no sustituye una autenticación de aplicación cuando se requiere conocer quién solicita el recurso.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'Authorization Cheat Sheet','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html','desc'=>'Refuerza el principio de validar autorización en cada solicitud y no asumir que un endpoint auxiliar está protegido únicamente porque normalmente es llamado desde una interfaz autenticada.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'REST Security Cheat Sheet','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html','desc'=>'Resume controles de autenticación y autorización para servicios HTTP. Es útil para analizar por qué una API de lectura también debe validar el contexto de seguridad del solicitante.'],
 ['type'=>'CWE','title'=>'CWE-306: Missing Authentication for Critical Function','url'=>'https://cwe.mitre.org/data/definitions/306.html','desc'=>'Describe el riesgo de exponer una función sensible sin comprobar una identidad cuando el recurso debería estar reservado a usuarios autenticados.'],
 ['type'=>'CWE','title'=>'CWE-862: Missing Authorization','url'=>'https://cwe.mitre.org/data/definitions/862.html','desc'=>'Complementa el análisis cuando existe un esquema de identidad o acceso general, pero una función concreta no comprueba si el solicitante está autorizado para utilizarla.'],
 ['type'=>'NIST','title'=>'SP 800-82 Rev. 3 · Guide to Operational Technology Security','url'=>'https://csrc.nist.gov/pubs/sp/800/82/r3/final','desc'=>'Contextualiza por qué la telemetría, las interfaces HMI y los servicios de soporte de OT requieren controles de acceso consistentes incluso dentro de segmentos de red restringidos.']
],
18=>[
 ['type'=>'Metodología','title'=>'Flujo de análisis offline de hashes','url'=>'https://www.kali.org/tools/hashid/','desc'=>'Empieza por clasificar el valor antes de intentar romperlo: conserva una copia original, separa prefijos descriptivos como sha1:, observa longitud y alfabeto, identifica si existe salt y confirma el formato con una herramienta. Sólo después elige el modo de cracking. En este laboratorio todo el análisis debe hacerse offline sobre el verificador proporcionado.'],
 ['type'=>'Kali Linux','title'=>'hashID · identificación de hashes','url'=>'https://www.kali.org/tools/hashid/','desc'=>'hashID reconoce más de un centenar de formatos y puede mostrar modos compatibles con Hashcat mediante -m. Es útil para confirmar que 40 caracteres hexadecimales son compatibles con SHA-1, pero la longitud por sí sola no constituye prueba suficiente: contrástala con el prefijo y el contexto del manifiesto.'],
 ['type'=>'Kali Linux','title'=>'hash-identifier','url'=>'https://www.kali.org/tools/hash-identifier/','desc'=>'Alternativa interactiva para identificar posibles tipos de hash. Úsala como segunda opinión cuando un digest pueda corresponder a varios formatos o construcciones.'],
 ['type'=>'Kali Linux','title'=>'Hashcat','url'=>'https://www.kali.org/tools/hashcat/','desc'=>'Herramienta principal para cracking offline. Para SHA-1 crudo consulta el modo 100. Flujo mínimo del laboratorio: guardar sólo el digest hexadecimal en un archivo; ejecutar hashcat -m 100 -a 0 hash.txt candidatos.txt; después consultar el resultado con hashcat -m 100 hash.txt --show. Empieza por diccionario antes de fuerza bruta.'],
 ['type'=>'Hashcat','title'=>'Hashcat Wiki · modos y ejemplos','url'=>'https://hashcat.net/wiki/doku.php?id=hashcat','desc'=>'Referencia para sintaxis, modos de ataque y uso de reglas. Los ataques de diccionario prueban candidatos de una lista; las reglas permiten transformar esos candidatos con mayúsculas, sufijos, números u otras mutaciones sin construir manualmente todas las variantes.'],
 ['type'=>'Kali Linux','title'=>'John the Ripper','url'=>'https://www.kali.org/tools/john/','desc'=>'Alternativa a Hashcat para análisis offline. Para un SHA-1 crudo puede utilizarse el formato raw-sha1 con una wordlist y luego john --show para recuperar el resultado. Es útil para comparar herramientas y confirmar un candidato sin depender de una sola implementación.'],
 ['type'=>'Openwall','title'=>'John the Ripper · cracking modes','url'=>'https://www.openwall.com/john/doc/MODES.shtml','desc'=>'Explica modos de diccionario, incremental y otras estrategias. Para este reto prioriza candidatos plausibles derivados del contexto antes de utilizar búsqueda exhaustiva.'],
 ['type'=>'Openwall','title'=>'John the Ripper · wordlist rules','url'=>'https://www.openwall.com/john/doc/RULES.shtml','desc'=>'Describe cómo las reglas transforman palabras base, por ejemplo cambios de mayúsculas y adición de dígitos. Es especialmente útil cuando el manifiesto sugiere términos como soporte, RTU, versión, build o números asociados a la actualización.'],
 ['type'=>'OWASP Cheat Sheet','title'=>'Password Storage Cheat Sheet','url'=>'https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html','desc'=>'Explica por qué SHA-1 y otras funciones rápidas no son adecuadas para almacenar contraseñas: permiten probar grandes cantidades de candidatos offline. Contrasta este residuo heredado con el bcrypt que utiliza el login moderno del laboratorio.'],
 ['type'=>'OWASP','title'=>'Cryptographic Failures','url'=>'https://top10.owasp.org/2025/A04_2025-Cryptographic_Failures/','desc'=>'Contextualiza el uso de algoritmos criptográficos obsoletos y recomienda funciones adaptativas y con salt para contraseñas. Ayuda a justificar por qué encontrar un SHA-1 heredado constituye un riesgo aunque el sistema actual use bcrypt.'],
 ['type'=>'OWASP','title'=>'IoT Security Testing Guide · Firmware','url'=>'https://owasp.org/owasp-istg/03_test_cases/firmware/index.html','desc'=>'Guía especializada para analizar firmware y mecanismos de actualización. Después de recuperar el acceso de mantenimiento, úsala para separar el análisis de credenciales del análisis del paquete de firmware.'],
 ['type'=>'CWE','title'=>'CWE-345: Insufficient Verification of Data Authenticity','url'=>'https://cwe.mitre.org/data/definitions/345.html','desc'=>'Distingue integridad de autenticidad: un contenido puede coincidir con un hash calculado por quien lo modificó sin demostrar que provenga de un emisor autorizado.'],
 ['type'=>'CWE','title'=>'CWE-347: Improper Verification of Cryptographic Signature','url'=>'https://cwe.mitre.org/data/definitions/347.html','desc'=>'Referencia para evaluar el paso final: una firma digital correctamente verificada sí puede aportar autenticidad cuando la clave pública confiable está anclada de forma adecuada.'],
 ['type'=>'NIST','title'=>'SP 800-193 · Platform Firmware Resiliency Guidelines','url'=>'https://csrc.nist.gov/pubs/sp/800/193/final','desc'=>'Presenta principios de protección, detección y recuperación de firmware. Úsalo para justificar qué propiedades debería verificar un proceso de actualización antes de aplicar un paquete.'],
 ['type'=>'NIST','title'=>'FIPS 180-4 · Secure Hash Standard','url'=>'https://csrc.nist.gov/pubs/fips/180-4/upd1/final','desc'=>'Referencia de SHA-1/SHA-2 y funciones hash. Ayuda a explicar qué significa recalcular un digest y por qué un hash sin secreto no autentica al creador de un paquete.'],
 ['type'=>'PowerShell','title'=>'Get-FileHash','url'=>'https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.utility/get-filehash','desc'=>'Útil para documentar SHA-256 de archivos. Para cadenas exactas del payload, asegúrate de no introducir saltos de línea o caracteres adicionales: el digest cambia ante cualquier diferencia de bytes.']
],
